import{_ as a,o as r,c as e,a2 as d}from"./chunks/framework.CYjxsSA2.js";const b=JSON.parse('{"title":"空间扫描","description":"","frontmatter":{},"headers":[],"relativePath":"guide/portscan.md","filePath":"guide/portscan.md"}'),o={name:"guide/portscan.md"};function l(i,t,n,s,h,c){return r(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="空间扫描" tabindex="-1">空间扫描 <a class="header-anchor" href="#空间扫描" aria-label="Permalink to &quot;空间扫描&quot;">​</a></h1><p>空间扫描提供多模式端口扫描与服务识别，是资产测绘的第一站。扫描结果可与漏洞测绘联动。</p><h2 id="扫描模式" tabindex="-1">扫描模式 <a class="header-anchor" href="#扫描模式" aria-label="Permalink to &quot;扫描模式&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模式</th><th>说明</th><th>适用</th></tr></thead><tbody><tr><td><strong>TCP Connect</strong></td><td>全连接扫描，兼容性最好</td><td>常规场景</td></tr><tr><td><strong>SYN</strong></td><td>高速扫描（不可用时回落 TCP）</td><td>大网段快扫</td></tr><tr><td><strong>UDP</strong></td><td>UDP 端口探测</td><td>DNS / SNMP 等服务</td></tr></tbody></table><h2 id="端口模板" tabindex="-1">端口模板 <a class="header-anchor" href="#端口模板" aria-label="Permalink to &quot;端口模板&quot;">​</a></h2><ul><li><strong>常用 / 主端口 / Web 服务 / 数据库 / 基础服务</strong> —— 面向不同服务面的定向模板</li><li><strong>Top 1000</strong> —— 高频端口快扫</li><li><strong>全端口</strong> —— 1–65535 全量覆盖</li></ul><p>也可以直接手写端口，如 <code>22,80,443</code>、<code>1-1000</code>。</p><h2 id="服务识别" tabindex="-1">服务识别 <a class="header-anchor" href="#服务识别" aria-label="Permalink to &quot;服务识别&quot;">​</a></h2><ul><li><strong>服务指纹</strong> —— 识别开放端口上跑的是什么服务</li><li><strong>Web 标题抓取</strong> —— 开放 HTTP 服务的站点标题自动提取</li><li><strong>TLS 证书</strong> —— 域名与有效期等信息</li><li><strong>离线 IP 归属</strong> —— 无需联网查询</li></ul><h2 id="结果与联动" tabindex="-1">结果与联动 <a class="header-anchor" href="#结果与联动" aria-label="Permalink to &quot;结果与联动&quot;">​</a></h2><ul><li>按端口、服务、状态过滤检索</li><li>结果可导出为文件，保存在数据目录的导出位置</li><li>点任意存活主机可查看关联信息</li><li>发现 Web 服务后可联动<a href="/vaelor/guide/webcrawl.html">漏洞测绘</a> 做站点深度分析</li></ul><h2 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td>目标</td><td>IP / 域名 / CIDR，支持多行；<strong>单次上限 1024 个主机</strong></td></tr><tr><td>端口</td><td>模板选择或手写端口表达式</td></tr><tr><td>模式</td><td>TCP Connect / SYN / UDP</td></tr><tr><td>速率</td><td>每秒发包数</td></tr><tr><td>并发 / 重试 / 超时</td><td>按网络状况调整</td></tr><tr><td>排除端口</td><td>跳过指定端口</td></tr></tbody></table><h2 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h2><ul><li>ICMP 存活探测在 macOS / Linux 下需要管理员权限，无权限时会回落系统 <code>ping</code>，速度明显变慢</li><li>Web 标题与证书是自动抓取的，站点有反爬或证书异常时可能为空</li><li>缺少 IP 归属离线库时，归属列全部显示「未知」，不影响其他字段</li><li>目标数超过上限会直接报错，大网段请按 <code>/24</code> 分批下发</li></ul><h2 id="典型流程" tabindex="-1">典型流程 <a class="header-anchor" href="#典型流程" aria-label="Permalink to &quot;典型流程&quot;">​</a></h2><ol><li>导入 CIDR（如 <code>10.1.5.0/24</code>）</li><li>选择 Top 1000 模板 + SYN 模式快扫</li><li>在结果中筛选 HTTP / HTTPS 服务</li><li>联动漏洞测绘，进入站点分析</li></ol>',17)])])}const g=a(o,[["render",l]]);export{b as __pageData,g as default};
